practice.starter:
def parse_roll(arg):
    # your code
    pass

practice.solution:
def parse_roll(arg):
    if 'd' not in arg:
        return [0, 0]
    a, b = arg.split('d', 1)
    if a == '' or b == '':
        return [0, 0]
    for ch in a + b:
        if ch not in '0123456789':
            return [0, 0]
    n = int(a)
    s = int(b)
    if n < 1 or s < 1:
        return [0, 0]
    return [n, s]

