def make_mask(names):
    # your code
    pass

practice.solution:
def make_mask(names):
    bits = {'KICK': 1, 'BAN': 2, 'VIEW_CHANNEL': 10, 'SEND_MESSAGES': 11, 'MODERATE_MEMBERS': 20}
    m = 0
    for n in names:
        if n in bits:
            m = m | (1 << bits[n])
    return m

