practice.solution:
def has_perm(mask, name):
    bits = {'KICK': 1, 'BAN': 2, 'VIEW_CHANNEL': 10, 'SEND_MESSAGES': 11, 'MODERATE_MEMBERS': 20}
    if name not in bits:
        return False
    return ((mask >> bits[name]) & 1) == 1

